import { RevisionCard } from '../revisionDeck';

// Module flashcards for modules 7–12 (BCBR, ICMR-NIE).
// Card counts are 50+ per module after atomic splitting; ids mf-<module>-<3-digit>.
// Original ids (…-001…-050) are bound to the same fact/theme; split-off pieces
// use fresh ids …-101, …-102, …. Grounded in the app's own past-question banks
// (assignment7–12.ts) and the official BCBR research-methodology curriculum.

export const MODULE_FLASHCARDS_SLICE: Record<number, RevisionCard[]> = {
  // ---- Module 7: Experimental study designs (clinical trials) ----
  7: [
    { id: 'mf-7-001', module: 7, front: 'Clinical trial', back: 'A planned experiment on HUMAN participants to assess the efficacy/effectiveness of an intervention (drug, vaccine, procedure). Prospective and comparative by design.' },
    { id: 'mf-7-002', module: 7, front: 'Study type of a randomized clinical trial', back: 'An EXPERIMENTAL (interventional) study — the investigator assigns the exposure, unlike observational studies where exposure is merely observed.' },
    { id: 'mf-7-003', module: 7, front: 'Prerequisites before conducting a clinical trial', back: 'ALL of: sample size determination · approval from the regulatory authority · agreement between investigators and sponsors.' },
    { id: 'mf-7-004', module: 7, front: 'IEC approval — requirement before a trial begins', back: 'Approval by the Institutional Ethics Committee (IEC) BEFORE initiation is mandatory for trials in India.' },
    { id: 'mf-7-101', module: 7, front: 'CTRI registration — requirement for trials in India', back: 'Registration with the Clinical Trials Registry of India (CTRI) is mandatory for trials in India.' },
    { id: 'mf-7-005', module: 7, front: 'Allocation concealment', back: 'The investigator is UNAWARE of the sequence of allocation of participants to study arms before and until assignment is complete — prevents selection bias at enrolment.' },
    { id: 'mf-7-006', module: 7, front: 'Allocation concealment vs blinding', back: 'Concealment = not knowing the NEXT assignment (protects the enrolment process, before allocation).\nBlinding = not knowing which arm a participant RECEIVED (protects outcome assessment, after allocation). They are different processes.' },
    { id: 'mf-7-007', module: 7, front: 'Open-label RCT', back: 'NO blinding — investigators, participants and data analysts are ALL aware of the treatment assignment (e.g. comparing suturing vs stapling). It is still a valid randomized trial.' },
    { id: 'mf-7-008', module: 7, front: 'Serious adverse event (SAE)', back: 'An untoward occurrence that results in death, is life-threatening, requires hospitalization or prolongation of hospitalization, or causes persistent disability/incapacity — must be reported promptly during a trial.' },
    { id: 'mf-7-009', module: 7, front: 'Clinical equipoise', back: 'Genuine uncertainty in the expert community about which trial arm is superior — the ethical foundation that makes randomization acceptable.' },
    { id: 'mf-7-010', module: 7, front: 'Co-intervention', back: 'Additional (unplanned) treatment or care received by participants during a trial, which can distort the outcome. BLINDING eliminates the problem of co-intervention.' },
    { id: 'mf-7-011', module: 7, front: 'Biased outcome ascertainment', back: 'Results when PARTICIPANTS report symptoms or outcomes differently (e.g. exaggerating improvement if they know they received the drug) — prevented by blinding; standardized elicitation technique does not cause it.' },
    { id: 'mf-7-012', module: 7, front: 'Types of RCT by objective', back: 'Prophylactic (prevention) · Therapeutic (treatment) · Diagnostic (comparing tests) · Screening (effect of screening on outcomes).' },
    { id: 'mf-7-013', module: 7, front: 'Prophylactic RCT', back: 'Tests a PREVENTIVE intervention in people who do not have the disease — e.g. a new herbal medicine to prevent pneumonia in the elderly, or a COVID-19 vaccine in children.' },
    { id: 'mf-7-014', module: 7, front: 'Therapeutic RCT', back: 'Tests a TREATMENT in participants who already have the disease under study (e.g. a new drug for established rheumatoid arthritis).' },
    { id: 'mf-7-015', module: 7, front: 'Diagnostic RCT', back: 'Compares diagnostic strategies/tests (e.g. test A vs test B) using patient-important outcomes such as accuracy, morbidity or mortality.' },
    { id: 'mf-7-016', module: 7, front: 'Screening RCT', back: 'Randomizes participants to screened vs unscreened groups to test whether SCREENING improves outcomes (e.g. reduced disease-specific mortality).' },
    { id: 'mf-7-017', module: 7, front: 'Adverse event (AE)', back: 'ANY untoward medical occurrence in a trial participant, whether or not related to the intervention.' },
    { id: 'mf-7-102', module: 7, front: 'Adverse drug reaction (ADR)', back: 'An adverse event for which CAUSALITY with the drug is established — a subset of adverse events.' },
    { id: 'mf-7-018', module: 7, front: 'Multicentre trial', back: 'A trial conducted simultaneously at several centres under a common protocol — increases recruitment and generalizability but demands centralized coordination and uniform procedures.' },
    { id: 'mf-7-019', module: 7, front: 'Trial phase assessing vaccine efficacy', back: 'Phase III — conducted in a SUSCEPTIBLE (at-risk) population, large enough to detect differences in disease incidence. Phase I is only safety/immunogenicity in healthy volunteers.' },
    { id: 'mf-7-020', module: 7, front: 'Comparator (active control)', back: 'A known EFFECTIVE treatment (standard of care) given to the control group — contrasted with a placebo, which is pharmacologically inactive.' },
    { id: 'mf-7-021', module: 7, front: 'Data Safety Monitoring Board (DSMB)', back: 'An INDEPENDENT group that periodically reviews accumulating safety and efficacy data during a trial and can recommend modification or early stopping to protect participants.' },
    { id: 'mf-7-022', module: 7, front: 'Procedures ensuring participant safety in a trial', back: 'ALL of: adverse event reporting · serious adverse event reporting · periodic follow-up · review by a Data Safety Monitoring Board.' },
    { id: 'mf-7-023', module: 7, front: 'Handling dropouts in trial analysis', back: 'Dropouts should NOT simply be excluded from the analysis — excluding them biases the results; participants are analysed in the arm to which they were randomized.' },
    { id: 'mf-7-024', module: 7, front: 'Intention-to-treat (ITT) analysis', back: 'Every randomized participant is analysed in the group to which they were ASSIGNED, regardless of adherence or dropout — preserves the benefits of randomization.' },
    { id: 'mf-7-025', module: 7, front: 'Per-protocol analysis', back: 'Analyses only participants who completed the protocol as planned — breaks randomization and is prone to bias; used only as a supplement to ITT.' },
    { id: 'mf-7-026', module: 7, front: 'RCT advantage — evidence and bias control', back: 'RCTs provide the highest level of evidence and control selection and confounding bias. (Minimal ethical issues is NOT an advantage.)' },
    { id: 'mf-7-103', module: 7, front: 'RCT advantage — temporality', back: 'The RCT establishes temporality of the association because allocation precedes the outcome.' },
    { id: 'mf-7-027', module: 7, front: 'Ethical concern of RCTs — withholding treatment', back: 'Randomization may withhold a potentially beneficial intervention from the control arm — addressed by informed consent plus long-term care and support of participants.' },
    { id: 'mf-7-104', module: 7, front: 'Ethical concern of RCTs — placebo use', back: 'Placebo use may deprive the control arm of care — addressed by informed consent plus long-term care and support of participants.' },
    { id: 'mf-7-028', module: 7, front: 'Loss to follow-up in a clinical trial', back: 'It DOES affect the study outcome — differential dropout between arms biases results and reduces power. It is a misconception that trials are unaffected by it.' },
    { id: 'mf-7-029', module: 7, front: 'Determinants of a trial\u2019s sample size', back: 'The HYPOTHESIS being tested (expected effect size, variability, $\\alpha$ and $\\beta$ error) — not the number of investigators or centres.' },
    { id: 'mf-7-030', module: 7, front: 'Source of selection bias in clinical trials', back: 'Non-representative consenting volunteers, or biased enrolment when allocation is not concealed — trials are NOT automatically free of selection bias.' },
    { id: 'mf-7-031', module: 7, front: 'Features of an RCT — the odd one out', back: 'Randomization · allocation concealment · blinding are RCT features. SIMPLE RANDOM SAMPLING is not — it is a survey sampling method, unrelated to trial design.' },
    { id: 'mf-7-032', module: 7, front: 'Randomization methods', back: 'Simple (pure chance) · Block (balanced numbers over time) · Stratified (randomize within subgroups of prognostic factors).' },
    { id: 'mf-7-033', module: 7, front: 'Block randomization', back: 'Participants are randomized in small blocks (e.g. of 4 or 6) so group SIZES stay balanced throughout enrolment — useful when recruitment is staggered.' },
    { id: 'mf-7-034', module: 7, front: 'Stratified randomization', back: 'Participants are first divided into strata by key PROGNOSTIC factors (e.g. age, disease severity), then randomized within each stratum — guarantees baseline balance on those factors.' },
    { id: 'mf-7-035', module: 7, front: 'Allocation concealment — central randomization', back: 'Telephone- or web-based CENTRAL randomization keeps the upcoming assignment unpredictable.' },
    { id: 'mf-7-105', module: 7, front: 'Allocation concealment — SNOSE', back: 'Sequentially numbered, opaque, sealed envelopes (SNOSE) hide the next assignment until allocation.' },
    { id: 'mf-7-106', module: 7, front: 'Allocation concealment — pharmacy-controlled', back: 'Pharmacy-controlled allocation dispenses the assignment, keeping the sequence hidden from enrollers.' },
    { id: 'mf-7-036', module: 7, front: 'ICH–GCP', back: 'Good Clinical Practice — the international ethical and scientific quality standard for designing, conducting, recording and reporting trials involving humans.' },
    { id: 'mf-7-037', module: 7, front: 'Overly restrictive exclusion criteria', back: 'Cause BOTH decreased external validity (narrow, unrepresentative sample) AND problems with recruitment (too few eligible participants).' },
    { id: 'mf-7-038', module: 7, front: 'Double blinding — what it prevents', back: 'Bias arising from researchers being able to INFLUENCE the data because they know the allocated groups — i.e. it addresses ascertainment/observer bias in outcome assessment.' },
    { id: 'mf-7-039', module: 7, front: 'Confounders in a clinical trial', back: 'Randomization balances both known and unknown confounders across arms at baseline, so confounding CAN be handled in a trial.' },
    { id: 'mf-7-040', module: 7, front: 'CONSORT statement', back: 'The international guideline for transparent REPORTING of randomized trials (checklist + flow diagram of participant flow through the trial).' },
    { id: 'mf-7-041', module: 7, front: 'Randomization vs matching', back: 'Randomization prospectively creates comparable groups and can handle MANY factors (including unknown ones); matching only controls the matched factors and is the mainstay of observational studies.' },
    { id: 'mf-7-042', module: 7, front: 'Placebo effect', back: 'Improvement attributable to the EXPECTATION of receiving treatment rather than the pharmacological action of the drug — the reason placebo controls are used.' },
    { id: 'mf-7-043', module: 7, front: 'Run-in period', back: 'A pre-randomization phase in which all participants receive identical management — used to assess compliance/eligibility and screen out non-adherers BEFORE randomization.' },
    { id: 'mf-7-044', module: 7, front: 'Crossover trial', back: 'Each participant receives BOTH interventions in sequence (order randomized); each participant serves as their own control — suited to stable, chronic conditions.' },
    { id: 'mf-7-045', module: 7, front: 'Washout period', back: 'An interval with no treatment between the two phases of a crossover trial, allowing the first intervention\u2019s effect to dissipate and preventing CARRY-OVER.' },
    { id: 'mf-7-046', module: 7, front: 'Cluster RCT', back: 'Randomizes GROUPS (villages, clinics, schools) rather than individuals — used when the intervention operates at group level (e.g. water chlorination); requires design-effect-adjusted sample size.' },
    { id: 'mf-7-047', module: 7, front: 'Non-inferiority trial', back: 'Tests whether a new treatment is NOT WORSE than the standard by a pre-specified margin — used when a superior effect is not expected but advantages exist (cost, safety, convenience).' },
    { id: 'mf-7-048', module: 7, front: 'Prospective trial registration', back: 'Registering the trial (e.g. in CTRI/clinicaltrials.gov) BEFORE enrolment prevents selective reporting and publication bias, and makes results findable.' },
    { id: 'mf-7-049', module: 7, front: 'Explanatory vs pragmatic trial', back: 'Explanatory = ideal conditions, measures EFFICACY (can it work?).\nPragmatic = routine conditions, measures EFFECTIVENESS (does it work in real practice?).' },
    { id: 'mf-7-050', module: 7, front: 'Blinding and protocol adherence', back: 'Blinding prevents biased assessment but does NOT make participants adhere to the protocol — adherence needs separate monitoring and reinforcement.' },

  ],

  8: [
    // ---- Module 8: Validity, bias and confounding ----
    { id: 'mf-8-001', module: 8, front: 'Cohort study — starting point', back: 'Starts with people EXPOSED to a risk factor but WITHOUT the disease (plus unexposed comparison), then follows them forward in time for outcomes.' },
    { id: 'mf-8-002', module: 8, front: 'Case-control study — starting point', back: 'Starts with people who ALREADY have the disease (cases) and comparable people without it (controls), then looks BACKWARD for prior exposure.' },
    { id: 'mf-8-003', module: 8, front: 'Measure of association in a case-control study', back: 'The ODDS RATIO (OR) — incidence and relative risk cannot be calculated directly because participants are sampled by outcome, not by exposure.' },
    { id: 'mf-8-004', module: 8, front: 'Measure of association in a cohort study', back: 'The RELATIVE RISK (RR) — because incidence in exposed and unexposed groups can be measured directly.' },
    { id: 'mf-8-005', module: 8, front: 'Relative Risk of 2.0 means…', back: 'The exposed group has TWICE the risk of the unexposed group. $RR < 1$ suggests a protective exposure; $RR = 1$ means no association.' },
    { id: 'mf-8-006', module: 8, front: 'Odds Ratio of 1.0 means…', back: 'There is NO association between exposure and disease. $OR > 1$ suggests a risk factor; $OR < 1$ suggests a protective exposure.' },
    { id: 'mf-8-007', module: 8, front: 'Rare disease assumption', back: 'The OR approximates the RR only when the disease/outcome is RARE. For common outcomes the OR overstates the RR.' },
    { id: 'mf-8-008', module: 8, front: 'Best design for a RARE EXPOSURE', back: 'COHORT study — a dedicated exposed group can be assembled and followed (e.g. workers exposed to a chemical). Rare diseases favour case-control instead.' },
    { id: 'mf-8-009', module: 8, front: 'Prospective cohort', back: 'Exposure is measured NOW and participants are followed FORWARD in time until outcomes occur — strongest for establishing temporality.' },
    { id: 'mf-8-010', module: 8, front: 'Retrospective (historical) cohort', back: 'Uses exposure data recorded in the PAST (records/registers) and traces outcomes that have already occurred — cheaper and faster, but depends on data quality.' },
    { id: 'mf-8-011', module: 8, front: 'Retrospective cohort vs case-control — starting point', back: 'Different starting points: a retrospective cohort starts from EXPOSURE status in past records; a case-control starts from OUTCOME (disease) status — so their measures differ.' },
    { id: 'mf-8-012', module: 8, front: 'Design that calculates incidence directly', back: 'The COHORT study — incidence (and RR, attributable risk) are computable; case-control and cross-sectional designs cannot yield incidence.' },
    { id: 'mf-8-013', module: 8, front: 'Cohort advantage — temporality and incidence', back: 'Cohorts document exposure before the outcome (temporality) and measure incidence directly, yielding RR.' },
    { id: 'mf-8-101', module: 8, front: 'Cohort advantage — multiple outcomes', back: 'One exposure can be studied for MANY outcomes within a single cohort.' },
    { id: 'mf-8-102', module: 8, front: 'Cohort advantage — rare exposures', back: 'Cohorts efficiently study RARE EXPOSURES — a dedicated exposed group is assembled and followed.' },
    { id: 'mf-8-014', module: 8, front: 'Cohort disadvantage — cost, time and loss to follow-up', back: 'Cohorts are expensive and time-consuming, and loss to follow-up shrinks the analysable sample.' },
    { id: 'mf-8-103', module: 8, front: 'Cohort disadvantage — rare diseases', back: 'Cohorts are inefficient for RARE DISEASES — too few cases accumulate during follow-up.' },
    { id: 'mf-8-104', module: 8, front: 'Cohort disadvantage — changing exposure status', back: 'Exposure status may change over long follow-up, complicating classification of the exposure.' },
    { id: 'mf-8-015', module: 8, front: 'Case-control advantage — speed, cost and rare diseases', back: 'Case-control studies are quick and inexpensive, are ideal for RARE DISEASES and outbreak investigations, and need few subjects.' },
    { id: 'mf-8-105', module: 8, front: 'Case-control advantage — multiple exposures', back: 'A single outcome can be linked to MANY prior exposures (one outcome → multiple exposures).' },
    { id: 'mf-8-016', module: 8, front: 'Case-control study — disadvantages', back: 'Prone to recall and selection bias · cannot calculate incidence or RR directly · temporality may be unclear · only ONE outcome can be studied.' },
    { id: 'mf-8-017', module: 8, front: 'Case-control study — choice of controls', back: 'People from the SAME population (source population) as the cases but WITHOUT the disease under study — not merely healthy volunteers or patients with unrelated diseases.' },
    { id: 'mf-8-018', module: 8, front: 'Nested case-control study', back: 'A case-control study conducted WITHIN a defined cohort — cases arise during cohort follow-up and controls are sampled from the same cohort.' },
    { id: 'mf-8-019', module: 8, front: 'Advantage of a nested case-control', back: 'Combines the efficiency of case-control with the reliable exposure data of a cohort — exposure was measured BEFORE the outcome, avoiding recall bias, at a fraction of the cost of analysing the whole cohort.' },
    { id: 'mf-8-020', module: 8, front: 'Preferred design for outbreak investigations', back: 'CASE-CONTROL — a small number of cases and controls can rapidly identify the suspected source (e.g. food item) without surveying everyone.' },
    { id: 'mf-8-021', module: 8, front: 'Design best establishing temporality', back: 'COHORT (and RCT) — exposure is documented before the outcome. In case-control and cross-sectional designs, temporality may be ambiguous.' },
    { id: 'mf-8-022', module: 8, front: 'Multiple outcomes vs multiple exposures', back: 'Cohort: one exposure → MANY outcomes.\nCase-control: one outcome (disease) → MANY exposures.' },
    { id: 'mf-8-023', module: 8, front: 'Cross-sectional study', back: 'Exposure and outcome measured SIMULTANEOUSLY at one point in time; measures PREVALENCE; cannot establish temporality (which came first?).' },
    { id: 'mf-8-024', module: 8, front: 'Odds Ratio — formula', back: 'From the 2×2 table: $OR = \\dfrac{a \\times d}{b \\times c}$, where $a$ = exposed cases, $b$ = exposed controls, $c$ = unexposed cases, $d$ = unexposed controls.' },
    { id: 'mf-8-025', module: 8, front: 'Relative Risk — formula', back: '$RR = \\dfrac{\\text{incidence in the EXPOSED}}{\\text{incidence in the UNEXPOSED}}$. A ratio of incidences (risk ratio); must come from a design that measures incidence.' },
    { id: 'mf-8-026', module: 8, front: 'Attributable risk (risk difference)', back: '$\\text{Incidence in exposed} - \\text{incidence in unexposed}$ — the ABSOLUTE excess risk caused by the exposure in the exposed group.' },
    { id: 'mf-8-027', module: 8, front: 'Attributable risk percent', back: 'The proportion of disease in the EXPOSED that is due to the exposure: $AR\\% = \\dfrac{RR - 1}{RR} \\times 100$.' },
    { id: 'mf-8-028', module: 8, front: 'Confounding', back: 'Distortion of the measured exposure–outcome association by a THIRD variable that is associated with both the exposure and (independently) the outcome.' },
    { id: 'mf-8-029', module: 8, front: 'Three criteria for a confounder', back: '1) Associated with the EXPOSURE · 2) Independently associated with the OUTCOME (a risk factor) · 3) NOT an intermediate step on the causal pathway between exposure and outcome.' },
    { id: 'mf-8-030', module: 8, front: 'Classic confounding example', back: 'An alcohol–lung cancer association is confounded by SMOKING: smoking is linked to drinking AND independently causes lung cancer.' },
    { id: 'mf-8-031', module: 8, front: 'Controlling confounding at the DESIGN stage', back: 'Randomization (balances all confounders) · Restriction (admit only a narrow category) · Matching (pair/group subjects on confounders).' },
    { id: 'mf-8-032', module: 8, front: 'Controlling confounding at the ANALYSIS stage', back: 'Stratification · Standardization · Multivariable (regression) analysis — these adjust for confounders only AFTER data collection.' },
    { id: 'mf-8-033', module: 8, front: 'Positive vs negative confounding', back: 'Positive confounding exaggerates the true association (observed estimate farther from the null) · negative confounding masks it (estimate pulled toward the null).' },
    { id: 'mf-8-034', module: 8, front: 'Effect modification vs confounding', back: 'A confounder DISTORTS the association and must be removed; an effect modifier genuinely ALTERS the strength of the association across strata (e.g. stronger effect in women) and should be reported, not adjusted away.' },
    { id: 'mf-8-035', module: 8, front: 'Stratified analysis (Mantel–Haenszel)', back: 'The association is computed within each stratum of the confounder and then pooled into a single ADJUSTED estimate (Mantel–Haenszel pooled OR/RR).' },
    { id: 'mf-8-036', module: 8, front: 'Individual vs frequency matching', back: 'Individual matching = each case is paired with one (or more) matched controls · frequency matching = controls are chosen so the GROUP has the same confounder distribution as the cases.' },
    { id: 'mf-8-037', module: 8, front: 'Overmatching', back: 'Matching on a variable that is part of the causal pathway or too closely tied to the exposure — reduces statistical efficiency and can bias the OR toward the null.' },
    { id: 'mf-8-038', module: 8, front: 'Measures a cohort study can yield', back: 'Incidence · relative risk (RR) · attributable risk (risk difference) · AR% — a uniquely rich set because incidence is directly measurable.' },
    { id: 'mf-8-039', module: 8, front: 'Sensitivity analysis', back: 'Repeating the analysis under different assumptions or definitions (e.g. varying how missing data are handled) to test whether conclusions are ROBUST.' },
    { id: 'mf-8-040', module: 8, front: 'Ecological fallacy', back: 'Erroneously inferring INDIVIDUAL-level associations from GROUP-level (aggregate) data — the core pitfall of ecological studies.' },
    { id: 'mf-8-041', module: 8, front: 'Incidence vs prevalence', back: 'Incidence = NEW cases arising during a defined period (flow).\nPrevalence = ALL existing cases at a point/period (stock).' },
    { id: 'mf-8-042', module: 8, front: 'Direct vs indirect standardization', back: 'Direct: applies the study population\u2019s stratum-specific rates to a STANDARD population structure.\nIndirect: applies standard rates to the study population\u2019s structure to give expected events (basis of the SMR).' },
    { id: 'mf-8-043', module: 8, front: 'Standardized Mortality Ratio (SMR)', back: '$\\dfrac{\\text{Observed deaths}}{\\text{Expected deaths}} \\times 100$ in the study population, where expected deaths come from applying reference rates — an INDIRECT standardization measure used in occupational cohort studies.' },
    { id: 'mf-8-044', module: 8, front: 'Multivariable regression for confounding', back: 'Adjusts for SEVERAL confounders simultaneously (logistic, Cox, linear regression) — the analysis-stage method of choice when multiple confounders must be controlled.' },
    { id: 'mf-8-045', module: 8, front: 'Berkson\u2019s bias — mechanism', back: 'Selecting cases and controls solely among HOSPITALIZED patients distorts the exposure–disease association, because hospitalization itself is related to the diseases studied — a spurious association can appear.' },
    { id: 'mf-8-046', module: 8, front: 'A cohort — how recall bias is avoided', back: 'Exposure is recorded PROSPECTIVELY, before the outcome is known — so participants\u2019 memory of exposure (the Achilles heel of case-control studies) is not involved.' },
    { id: 'mf-8-047', module: 8, front: 'Data sources for a historical cohort', back: 'Employment/occupational records · medical records · disease registries · insurance or prescription databases — any source documenting exposure and outcomes from the past.' },
    { id: 'mf-8-048', module: 8, front: 'RCTs — handling of confounding', back: 'Randomization balances both KNOWN and UNKNOWN confounders across arms; observational designs must identify and measure each confounder to control it.' },
    { id: 'mf-8-049', module: 8, front: 'Restriction as confounder control', back: 'The simplest design-stage method — admit only one category of the confounder (e.g. non-smokers only). Cheap and easy, but limits generalizability and cannot address unknown confounders.' },
    { id: 'mf-8-050', module: 8, front: 'Chance vs bias as explanations for a finding', back: 'Chance (random error) is addressed by p-values and confidence intervals; bias is systematic and persists no matter how the analysis is framed — a precise estimate can still be wrong.' },

  ],

  9: [
    // ---- Module 9: Qualitative research methods ----
    { id: 'mf-9-001', module: 9, front: 'Purpose of qualitative research', back: 'To EXPLORE and understand perceptions, practices, motivations and the social context of behaviour — the WHY behind what people do, from the participants\u2019 point of view.' },
    { id: 'mf-9-002', module: 9, front: 'Characteristics of qualitative research methods', back: 'Subjective · credible · INDUCTIVE · based on INTERPRETATION of responses (contrast: quantitative = objective, measurable, repeatable).' },
    { id: 'mf-9-003', module: 9, front: 'Logic of inquiry in qualitative research', back: 'INDUCTIVE — specific observations build toward general understanding/theory (quantitative research works the other way, deductively).' },
    { id: 'mf-9-004', module: 9, front: 'Action verbs for qualitative objectives', back: 'EXPLORE, understand, perceive, describe. Verbs like ESTIMATE, DETERMINE, PREDICT belong to quantitative objectives.' },
    { id: 'mf-9-005', module: 9, front: 'Form of qualitative data', back: 'TEXT — interview transcripts, field notes, documents. Hypothesis TESTING is not a goal; interpretation is.' },
    { id: 'mf-9-006', module: 9, front: 'When to use qualitative methods', back: 'For UNFAMILIAR or insufficiently researched topics · seeking depth of understanding · exploring behaviours · viewing a phenomenon HOLISTICALLY.' },
    { id: 'mf-9-007', module: 9, front: 'When qualitative methods are NOT appropriate', back: 'For a FAMILIAR, sufficiently researched matter (nothing new to explore) — and they can never measure prevalence/incidence or test associations.' },
    { id: 'mf-9-008', module: 9, front: 'Mixed-methods study', back: 'Combines quantitative and qualitative components in one study — e.g. a survey to estimate exclusive breastfeeding prevalence PLUS interviews to understand myths and taboos around it.' },
    { id: 'mf-9-009', module: 9, front: 'Emic perspective', back: 'The INSIDER\u2019s (participant\u2019s) own point of view — the perspective qualitative research, especially in-depth interviews, is designed to capture.' },
    { id: 'mf-9-010', module: 9, front: 'Etic perspective', back: 'The OUTSIDER\u2019s (researcher\u2019s) scientific/external viewpoint — contrasted with the emic (insider) perspective.' },
    { id: 'mf-9-011', module: 9, front: 'Qualitative research — point of view interpreted', back: 'The PARTICIPANT\u2019s — social reality is interpreted from the participants\u2019 point of view, not the investigator\u2019s.' },
    { id: 'mf-9-012', module: 9, front: 'Interview guide', back: 'A flexible, open-ended list of topics/questions used in in-depth interviews and FGDs — it steers the conversation without the rigidity of a structured questionnaire.' },
    { id: 'mf-9-013', module: 9, front: 'Rapport in qualitative interviewing', back: 'The trust and comfort built between interviewer and participant — essential for candid responses, especially on sensitive topics.' },
    { id: 'mf-9-014', module: 9, front: 'Best method for highly sensitive personal topics', back: 'IN-DEPTH INTERVIEW — one-to-one privacy suits domestic abuse, alcohol use, or non-compliance among adolescent IV drug users. FGDs are unsuitable here.' },
    { id: 'mf-9-015', module: 9, front: 'In-depth interview — analysis burden', back: 'IDI transcripts are TIME-CONSUMING to analyse, and the method requires skilled interviewers.' },
    { id: 'mf-9-101', module: 9, front: 'In-depth interview — generalizability', back: 'Findings are NOT generalizable (small, purposive samples) — a key limitation of the IDI.' },
    { id: 'mf-9-016', module: 9, front: 'In-depth interview — number of participants per session', back: 'ONE participant at a time — involving two or more participants at once would disqualify it as an IDI.' },
    { id: 'mf-9-017', module: 9, front: 'FGD team — moderator', back: 'The MODERATOR facilitates the discussion using the interview guide.' },
    { id: 'mf-9-102', module: 9, front: 'FGD team — note-taker', back: 'The NOTE-TAKER/recorder documents what is said and the group dynamics.' },
    { id: 'mf-9-018', module: 9, front: 'Prerequisites of a focus group discussion', back: 'Homogeneous participants · genuine group interaction · a flexible interview guide. PERSONAL/sensitive topics are NOT a prerequisite — they are a disqualifier.' },
    { id: 'mf-9-019', module: 9, front: 'Group interaction in an FGD — its role', back: 'The interchange between participants (agreement, challenge, storytelling) generates insights no single interview could — it is integral to an effective discussion.' },
    { id: 'mf-9-020', module: 9, front: 'FGD suitability for sensitive personal behaviour', back: 'UNSUITABLE — participants are unlikely to disclose personal behaviours on sensitive issues in a group, so such data are not easy to obtain in an FGD.' },
    { id: 'mf-9-021', module: 9, front: 'When an FGD is the method of choice', back: 'To gather a WIDE range of information on a topic in a SHORT time (e.g. child feeding practices).' },
    { id: 'mf-9-103', module: 9, front: 'FGD use — learning local terminology', back: 'FGDs quickly reveal LOCAL TERMINOLOGIES and forms of a practice (e.g. types of tobacco used).' },
    { id: 'mf-9-022', module: 9, front: 'Bias risk in FGD data', back: 'TRUE — data from focus group discussions may be sensitive to BIASED analysis (dominant voices, groupthink, selective quoting).' },
    { id: 'mf-9-023', module: 9, front: 'Participant observation', back: 'The researcher becomes PART of the group/event being studied (immersion) — e.g. living in the community to learn local terms and practices.' },
    { id: 'mf-9-024', module: 9, front: 'Participant observation — data collection difficulty', back: 'SYSTEMATIC data collection is difficult during participant observation.' },
    { id: 'mf-9-104', module: 9, front: 'Participant observation — analytic methods', back: 'Analytic methods for observational data are not well described.' },
    { id: 'mf-9-105', module: 9, front: 'Participant observation — time demand', back: 'Participant observation is time-intensive because it requires prolonged immersion.' },
    { id: 'mf-9-025', module: 9, front: 'Participant observation — data richness', back: 'Produces very DETAILED, contextual data — rich rather than concise.' },
    { id: 'mf-9-106', module: 9, front: 'Participant observation — natural behaviour', back: 'Captures natural behaviour as it happens, without the reactivity of an interview.' },
    { id: 'mf-9-026', module: 9, front: 'Key informant interview', back: 'An interview with a selected, KNOWLEDGEABLE member of the community (e.g. an ANM, teacher, elder) who can speak about the community\u2019s practices and views.' },
    { id: 'mf-9-027', module: 9, front: 'Sociogram', back: 'NOT a qualitative data collection method — it is a diagram mapping social relationships within a group. Interviews, FGDs and participant observation ARE collection methods.' },
    { id: 'mf-9-028', module: 9, front: 'Ethnography', back: 'Prolonged immersion in a community to describe its CULTURE — beliefs, practices and social organization — from within.' },
    { id: 'mf-9-029', module: 9, front: 'Content analysis', back: 'The qualitative analysis method that uses a pre-existing THEORETICAL FRAMEWORK as the basis for coding and interpreting the text.' },
    { id: 'mf-9-030', module: 9, front: 'Grounded theory vs content analysis', back: 'Grounded theory BUILDS the theory FROM the data (code → categories → theory); content analysis STARTS from an existing theoretical framework.' },
    { id: 'mf-9-031', module: 9, front: 'Hermeneutics & schema analysis', back: 'Other qualitative analysis approaches — hermeneutics interprets the MEANING of texts; schema analysis examines the mental frameworks (schemas) reflected in accounts.' },
    { id: 'mf-9-032', module: 9, front: 'Thematic analysis', back: 'Identifying, analysing and reporting recurring THEMES (patterns of meaning) across the dataset — a widely used approach for interview/FGD transcripts.' },
    { id: 'mf-9-033', module: 9, front: 'Coding (qualitative analysis)', back: 'Labelling segments of text with descriptive tags; the first analytical step — codes are grouped into categories and then themes or theory.' },
    { id: 'mf-9-034', module: 9, front: 'Purposive sampling', back: 'Participants are deliberately selected because they are INFORMATION-RICH for the research question — the characteristic sampling approach of qualitative research.' },
    { id: 'mf-9-035', module: 9, front: 'Snowball sampling', back: 'Early participants REFER others like themselves — useful for hard-to-reach or hidden populations (e.g. injecting drug users).' },
    { id: 'mf-9-036', module: 9, front: 'Convenience sampling', back: 'Recruiting whoever is easily available — quick but prone to selection bias; weakest qualitative sampling choice.' },
    { id: 'mf-9-037', module: 9, front: 'Data saturation', back: 'The point at which further interviews yield NO NEW information or themes — the standard signal to stop recruiting in qualitative research.' },
    { id: 'mf-9-038', module: 9, front: 'Sample size in qualitative research', back: 'Small and determined by SATURATION (not by power calculations) — depth and richness matter more than representativeness.' },
    { id: 'mf-9-039', module: 9, front: 'Trustworthiness criteria in qualitative research', back: 'Credibility (≈ internal validity) · Transferability (≈ external validity) · Dependability (≈ reliability) · Confirmability (≈ objectivity).' },
    { id: 'mf-9-040', module: 9, front: 'Reflexivity', back: 'The researcher\u2019s continuous reflection on how their OWN background, role and assumptions influence the data collection and interpretation.' },
    { id: 'mf-9-041', module: 9, front: 'Field notes', back: 'The written record kept during/after participant observation — descriptions of behaviour, setting, conversations and the observer\u2019s reflections.' },
    { id: 'mf-9-042', module: 9, front: 'Verbatim transcription', back: 'A word-for-word written record of an audio-recorded interview or FGD — the raw material for qualitative coding and analysis.' },
    { id: 'mf-9-043', module: 9, front: 'Recording interviews and FGDs', back: 'Audio/video recording CAN be done — only with PRIOR INFORMED CONSENT of participants; never without it.' },
    { id: 'mf-9-044', module: 9, front: 'Confidentiality in qualitative research', back: 'Transcripts must be anonymized, identifiers removed and quotations presented so participants cannot be recognized — especially critical for stigmatizing topics.' },
    { id: 'mf-9-045', module: 9, front: 'Hypothesis generation', back: 'Qualitative studies are ideal for GENERATING ideas/hypotheses that quantitative studies (cohort, trial) can subsequently test.' },
    { id: 'mf-9-046', module: 9, front: 'Utilities of qualitative research', back: 'Insight into WHY people behave a certain way · deep understanding of a phenomenon · understanding the results of a quantitative study · viewing a social phenomenon holistically.' },
    { id: 'mf-9-047', module: 9, front: 'FGD vs IDI — efficiency trade-off', back: 'FGD saves time (several participants per session) and reveals GROUP NORMS through interaction; IDI offers depth and privacy but one voice at a time.' },
    { id: 'mf-9-048', module: 9, front: 'Document analysis', back: 'A qualitative data collection method — systematic review of existing documents (records, letters, reports, media) for themes and meanings.' },
    { id: 'mf-9-049', module: 9, front: 'Method triangulation', back: 'Using MULTIPLE METHODS for a comprehensive understanding of the phenomenon.' },
    { id: 'mf-9-107', module: 9, front: 'Source triangulation', back: 'Using MULTIPLE INFORMANTS/sources to strengthen understanding of the phenomenon.' },
    { id: 'mf-9-108', module: 9, front: 'Theory triangulation', back: 'Interpreting the data through MULTIPLE THEORIES.' },
    { id: 'mf-9-109', module: 9, front: 'Investigator triangulation', back: 'Involving MULTIPLE INVESTIGATORS in collection and analysis to reduce individual bias.' },
    { id: 'mf-9-050', module: 9, front: 'Maximum variation sampling', back: 'Deliberately sampling participants who are as DIVERSE as possible on key characteristics, to capture the full range of perspectives on the phenomenon.' },

  ],

  10: [
    // ---- Module 10: Measurement of study variables (basic statistics) ----
    { id: 'mf-10-001', module: 10, front: 'Quantitative vs qualitative variables', back: 'Quantitative (numerical): measured on a numeric scale (height, Hb, cholesterol).\nQualitative (categorical): categories (sex, blood group, SES class).' },
    { id: 'mf-10-002', module: 10, front: 'Nominal variable', back: 'Unordered categories with no ranking — eye colour, place of residence, blood group, sex. Only the MODE summarizes it.' },
    { id: 'mf-10-003', module: 10, front: 'Ordinal variable', back: 'CATEGORIES with a meaningful ORDER but unequal/unknown gaps — BP stages (normal → pre-hypertension → stage 1 → stage 2), SES classes, cancer stages.' },
    { id: 'mf-10-004', module: 10, front: 'Continuous variable', back: 'Can take ANY value (including decimals) within a range — height, cholesterol level, haemoglobin. Expressed in measurement units.' },
    { id: 'mf-10-005', module: 10, front: 'Discrete variable', back: 'Whole-number COUNTS only — number of children per household, number of admissions. Number of children is NOT a continuous variable.' },
    { id: 'mf-10-006', module: 10, front: 'Variable type of age', back: 'Age is a QUANTITATIVE (continuous, ratio-scale) variable — not nominal. Gender, place of residence and eye colour are the nominal ones.' },
    { id: 'mf-10-007', module: 10, front: 'Measures of central tendency', back: 'Mean · Median · Mode — three ways to describe the centre of a distribution.' },
    { id: 'mf-10-008', module: 10, front: 'Arithmetic mean', back: 'Sum of all observations ÷ number of observations. It USES every value in the dataset — which also makes it sensitive to extremes.' },
    { id: 'mf-10-009', module: 10, front: 'Median — definition', back: 'The middle value when observations are ordered. With an EVEN number of observations, it is the mean of the two middle values.' },
    { id: 'mf-10-010', module: 10, front: 'Median worked example', back: 'Data 12, 26, 10, 29, 48 → ordered 10, 12, 26, 29, 48 → median = 26 (the 3rd of 5 values).' },
    { id: 'mf-10-011', module: 10, front: 'Mode', back: 'The most FREQUENT value. A distribution may have no mode, one mode, or several (bimodal). E.g. in Hb values 10.0, 8.5, 12.0, 14.0, 11.5, 13.5, 9.0, 12.0, 11.3, 7.5 the mode is 12.0.' },
    { id: 'mf-10-012', module: 10, front: 'Dispersion measures — the one that does NOT belong', back: 'MODE (and MEAN) — they are central tendency measures. Range, variance, SD, IQR, mean deviation and CV are dispersion measures.' },
    { id: 'mf-10-013', module: 10, front: 'Measures of dispersion — the list', back: 'Range · Interquartile range · Mean deviation · Variance · Standard deviation · Coefficient of variation.' },
    { id: 'mf-10-014', module: 10, front: 'Range — key weakness', back: '$\\text{Range} = \\text{Maximum} - \\text{Minimum}$: uses only TWO values, so a single extreme value can grossly inflate it — the least stable dispersion measure.' },
    { id: 'mf-10-015', module: 10, front: 'Percentiles', back: 'Percentiles divide ORDERED data into 100 equal parts — a positional (rank-based) measure.' },
    { id: 'mf-10-101', module: 10, front: 'Deciles', back: 'Deciles divide ordered data into 10 equal parts.' },
    { id: 'mf-10-102', module: 10, front: 'Quartiles', back: 'Quartiles divide ordered data into 4 equal parts ($Q_1$, $Q_2$, $Q_3$).' },
    { id: 'mf-10-016', module: 10, front: 'IQR worked example', back: '$Q_1 = 8.5$ kg, $Q_3 = 16$ kg → $IQR = 16 - 8.5 = 7.5$ kg (the middle 50% of body weights).' },
    { id: 'mf-10-017', module: 10, front: 'Quartiles & counting patients', back: 'If FEV\u2019s $Q_1 = 1.5$ L and $Q_3 = 3.0$ L, the middle 50% of the 100 COPD patients — i.e. 50 patients — lie between 1.5 and 3.0 litres.' },
    { id: 'mf-10-018', module: 10, front: 'IQR and extreme values', back: 'The IQR is NOT influenced by extreme values — being based on positions ($Q_3 - Q_1$) — unlike the range, mean or SD.' },
    { id: 'mf-10-019', module: 10, front: 'Median with open-ended or ranked data', back: 'When data contain open-ended classes (e.g. \u201c>100\u201d) or are only ranked, the MEDIAN is preferred — it needs no exact values at the extremes.' },
    { id: 'mf-10-020', module: 10, front: 'Positional measures — the odd one out', back: 'Quartiles, percentiles, deciles and the median divide observations into equal parts. STANDARD DEVIATION does not — it is not a positional measure.' },
    { id: 'mf-10-021', module: 10, front: 'Measures affected by outliers', back: 'Affect: mean, SD, range.\nSpare: median, IQR, mode — rank-based and frequency-based measures are robust to extremes.' },
    { id: 'mf-10-022', module: 10, front: 'Sum of deviations from the mean', back: 'Always ZERO — deviations above and below the mean exactly cancel. This is why squared (or absolute) deviations are used in variance/SD.' },
    { id: 'mf-10-023', module: 10, front: 'Variance', back: '$\\text{Variance} = SD^2$ — the average of the SQUARED deviations of observations from the ARITHMETIC MEAN — deviations are always taken from the mean, never from the mode or median.' },
    { id: 'mf-10-024', module: 10, front: 'Standard deviation — definition and units', back: '$SD = \\sqrt{\\dfrac{\\sum (x - \\bar{x})^2}{n}}$ — the square root of the average squared deviation from the mean; expressed in the SAME units as the observations.' },
    { id: 'mf-10-103', module: 10, front: 'Standard deviation — status', back: 'The most important and most commonly used measure of dispersion.' },
    { id: 'mf-10-025', module: 10, front: 'The square of the SD — its name', back: 'The VARIANCE — not the \u201cmean deviation\u201d. (Mean deviation = average of absolute deviations from the mean.)' },
    { id: 'mf-10-026', module: 10, front: 'Coefficient of variation — worked examples', back: '$CV = \\dfrac{SD}{\\bar{x}} \\times 100\\%$.\nMean 110, SD 11 → 10% · Mean 25, SD 5 → 20%.' },
    { id: 'mf-10-027', module: 10, front: 'CV as the dispersion measure of choice — setting', back: 'When COMPARING variability across variables measured in DIFFERENT units (e.g. height in cm vs weight in kg), or comparing the precision of two methods/instruments — CV is unit-free.' },
    { id: 'mf-10-028', module: 10, front: 'Mean\u2019s defining property', back: 'The arithmetic mean is the only average into which EVERY observation enters — change one value and the mean changes (unlike median/mode).' },
    { id: 'mf-10-029', module: 10, front: 'Normal (Gaussian) distribution', back: 'Symmetric, bell-shaped; mean = median = mode; defined by two parameters (mean and SD). Skewness = 0.' },
    { id: 'mf-10-030', module: 10, front: '68–95–99.7 rule', back: 'In a normal distribution, approximately 68% of observations lie within 1 SD of the mean, 95% within 2 SD, and 99.7% within 3 SD.' },
    { id: 'mf-10-031', module: 10, front: 'Positively skewed distribution', back: 'TAIL points to the RIGHT (toward high values); a few large values pull the mean above the median ($\\text{mean} > \\text{median}$).' },
    { id: 'mf-10-032', module: 10, front: 'Negatively skewed distribution', back: 'TAIL points to the LEFT (toward low values); a few small values pull the mean below the median ($\\text{mean} < \\text{median}$).' },
    { id: 'mf-10-033', module: 10, front: 'Only average usable for nominal data', back: 'The MODE — nominal categories have no order, so a mean or median cannot be computed.' },
    { id: 'mf-10-034', module: 10, front: 'Frequency distribution', back: 'A table listing values (or class intervals) of a variable together with the NUMBER of observations in each — the basic way to summarize raw data.' },
    { id: 'mf-10-035', module: 10, front: 'Histogram', back: 'Bar diagram for CONTINUOUS data — adjacent bars touch (no gaps) because the underlying scale is continuous; area of bars ∝ frequency.' },
    { id: 'mf-10-036', module: 10, front: 'Bar chart', back: 'For CATEGORICAL (nominal/ordinal) data — bars are separated by gaps because categories are discrete entities.' },
    { id: 'mf-10-037', module: 10, front: 'Scatter diagram', back: 'Plots one continuous variable against another to display the RELATIONSHIP/correlation between them (e.g. height vs weight).' },
    { id: 'mf-10-038', module: 10, front: 'Line diagram', back: 'Displays TRENDS over time (e.g. annual TB incidence).' },
    { id: 'mf-10-104', module: 10, front: 'Pie chart', back: 'Shows proportions of a WHOLE (categorical composition).' },
    { id: 'mf-10-039', module: 10, front: 'Average for ordinal data', back: 'The MEDIAN — ordinal categories are ordered but not numeric, so a mean is inappropriate.' },
    { id: 'mf-10-040', module: 10, front: 'Average for symmetric, continuous data', back: 'The MEAN — with no skew or outliers it uses all information and is the most efficient summary.' },
    { id: 'mf-10-041', module: 10, front: 'Outlier', back: 'An observation abnormally distant from the rest of the data — it distorts the mean and SD, so always screen data for outliers before summarizing.' },
    { id: 'mf-10-042', module: 10, front: 'Bimodal distribution', back: 'A distribution with two peaks — often signals that the sample mixes TWO different subpopulations (e.g. two age groups); investigate before averaging.' },
    { id: 'mf-10-043', module: 10, front: 'Interval scale', back: 'Equal intervals but NO true zero (e.g. temperature in °C), so ratios are not meaningful.' },
    { id: 'mf-10-105', module: 10, front: 'Ratio scale', back: 'Has a TRUE zero, so ratios are meaningful (weight, height, haemoglobin).' },
    { id: 'mf-10-044', module: 10, front: 'Z-score (standard score)', back: '$Z = \\dfrac{x - \\text{mean}}{SD}$ — expresses how many standard deviations an observation lies above (+) or below (−) the mean.' },
    { id: 'mf-10-045', module: 10, front: 'Quartile deviation (semi-IQR)', back: '$\\dfrac{Q_3 - Q_1}{2}$ — half the interquartile range; a robust positional measure of spread.' },
    { id: 'mf-10-046', module: 10, front: 'Standard normal distribution', back: 'A normal distribution standardized to mean = 0 and SD = 1; any normal variable can be converted to it via z-scores.' },
    { id: 'mf-10-047', module: 10, front: 'Effect of adding a constant to every value', back: 'The mean and median SHIFT by the constant, but the SD (and variance, IQR) are UNCHANGED — dispersion is unaffected by shifting the origin.' },
    { id: 'mf-10-048', module: 10, front: 'Median in positional terms', back: 'Exactly 50% of ordered observations lie BELOW the median — the 50th percentile, the middle of the distribution.' },
    { id: 'mf-10-049', module: 10, front: 'Variance — units', back: 'SQUARED units of the original variable ($\\text{kg}^2$, $\\text{mg/dL}^2$) — the reason we take the square root to get the SD back into original units.' },
    { id: 'mf-10-050', module: 10, front: 'Median with an odd number of observations', back: 'Simply the MIDDLE value after sorting — e.g. the 5th of nine ordered scores. No averaging of two values is needed.' },

  ],

  11: [
    // ---- Module 11: Bias (selection & information) ----
    { id: 'mf-11-001', module: 11, front: 'Two broad classes of bias', back: 'SELECTION bias (errors in who is chosen/retained) and INFORMATION bias (errors in what is measured) — confounding is usually treated as a third, separate distorting mechanism.' },
    { id: 'mf-11-002', module: 11, front: 'Selection bias — definition', back: 'A systematic error arising from how participants are selected or retained, so the study population is NOT REPRESENTATIVE of the target population.' },
    { id: 'mf-11-003', module: 11, front: 'Information bias — definition', back: 'A systematic error in the MEASUREMENT or CLASSIFICATION of exposure or outcome (how information is collected), not in who is selected.' },
    { id: 'mf-11-004', module: 11, front: 'Interviewer bias', back: 'The interviewer elicits, probes or records answers DIFFERENTLY for different study groups (e.g. probing cases more intensely) — an information bias.' },
    { id: 'mf-11-005', module: 11, front: 'Observer / ascertainment bias', back: 'The person assessing the OUTCOME is influenced by knowledge of the participant\u2019s exposure or group — biased outcome assessment.' },
    { id: 'mf-11-006', module: 11, front: 'Recall bias remedy — standardized instrument', back: 'Use standardized, structured questionnaires so exposure recall is elicited comparably across study groups.' },
    { id: 'mf-11-101', module: 11, front: 'Recall bias remedy — objective records', back: 'Use objective records (lab results, registers) instead of memory wherever possible.' },
    { id: 'mf-11-102', module: 11, front: 'Recall bias remedy — incident cases', back: 'Select NEWLY diagnosed cases, who are temporally closer to the exposure event.' },
    { id: 'mf-11-103', module: 11, front: 'Recall bias remedy — bridging interviews', back: 'Bridge interviews aid memory by anchoring exposure recall to memorable life events.' },
    { id: 'mf-11-007', module: 11, front: 'Social desirability bias', back: 'Participants under-report stigmatized behaviours (alcohol, smoking) or over-report virtuous ones — an information bias arising from self-report.' },
    { id: 'mf-11-008', module: 11, front: 'Volunteer (self-selection) bias', back: 'People who VOLUNTEER for studies differ systematically from those who do not (often more health-conscious) — a selection bias.' },
    { id: 'mf-11-009', module: 11, front: 'Non-response bias', back: 'Occurs when people who REFUSE or fail to participate differ systematically from those who participate — a selection bias. Contrast: interviewer bias is an information bias.' },
    { id: 'mf-11-010', module: 11, front: 'Referral bias', back: 'Patients reaching a specialist/tertiary hospital are a non-representative (often more severe) subset — studying only them distorts estimates of the disease pattern in the community.' },
    { id: 'mf-11-011', module: 11, front: 'Publication bias', back: 'Studies with positive/statistically significant results are more likely to be PUBLISHED — distorts literature reviews and meta-analyses; countered by trial registration.' },
    { id: 'mf-11-012', module: 11, front: 'Diagnostic suspicion bias', back: 'Knowledge of the subject\u2019s EXPOSURE leads to a more intensive diagnostic work-up for the outcome — the outcome is detected more often in the exposed.' },
    { id: 'mf-11-013', module: 11, front: 'Exposure suspicion bias', back: 'Knowledge of the subject\u2019s OUTCOME (disease) leads to a more rigorous search for exposure — typical of case-control interviews.' },
    { id: 'mf-11-014', module: 11, front: 'Misclassification bias', back: 'Wrongly classifying exposure or outcome status (e.g. a diseased person labelled non-diseased) because tests/self-reports are imperfect — an INFORMATION bias.' },
    { id: 'mf-11-015', module: 11, front: 'Misclassification of exposure vs of outcome', back: 'Either can be misclassified: a smoker recorded as non-smoker (exposure), or a true case labelled a non-case (outcome). Both distort the measured association.' },
    { id: 'mf-11-016', module: 11, front: 'Reducing misclassification — valid instruments', back: 'Use VALID, standardized instruments and objective criteria, with exposure and outcome defined operationally in advance.' },
    { id: 'mf-11-104', module: 11, front: 'Reducing misclassification — training and technique', back: 'Train and calibrate measurers and use the best available test to limit misclassification.' },
    { id: 'mf-11-017', module: 11, front: 'Hawthorne effect', back: 'Participants change their behaviour simply because they KNOW they are being observed/studied — distorts observed behaviour from the natural state.' },
    { id: 'mf-11-018', module: 11, front: 'Observer-expectancy effect', back: 'The researcher\u2019s EXPECTATIONS unconsciously influence how outcomes are measured or interpreted — countered by blinding and standardized protocols.' },
    { id: 'mf-11-019', module: 11, front: 'Lead-time bias', back: 'Screening detects disease EARLIER, so survival from diagnosis looks longer even if time of death is unchanged — an artifact of the earlier starting clock.' },
    { id: 'mf-11-020', module: 11, front: 'Length-time bias', back: 'Screening disproportionately detects SLOW-GROWING, better-prognosis cases (they linger in the pre-clinical phase) — making screened cases look artificially healthier.' },
    { id: 'mf-11-021', module: 11, front: 'Neyman (prevalence–incidence) bias', back: 'Studying only SURVIVORS with prevalent disease misses fatal and short-lived cases — the exposure–disease picture is distorted by who survived to be studied.' },
    { id: 'mf-11-022', module: 11, front: 'Digit preference bias', back: 'Measurers ROUND values to favourite digits (e.g. BP recorded as 120/80) — a measurement (information) bias avoided by calibrated instruments and training.' },
    { id: 'mf-11-023', module: 11, front: 'Attrition bias', back: 'Differential DROPOUT between study groups (e.g. sicker participants leaving one arm) — a selection-type bias operating during follow-up.' },
    { id: 'mf-11-024', module: 11, front: 'Performance bias', back: 'Systematic differences in the CARE or intervention provided apart from the one being evaluated (co-interventions, different attention) — reduced by blinding and standardized protocols.' },
    { id: 'mf-11-025', module: 11, front: 'Detection bias', back: 'The OUTCOME is identified/ascertained differently between study groups (e.g. unblinded assessors investigate the treatment arm more) — reduced by blinded, identical outcome assessment.' },
    { id: 'mf-11-026', module: 11, front: 'Minimizing selection bias at recruitment', back: 'Clear eligibility criteria, a defined sampling frame and protocolized selection.' },
    { id: 'mf-11-105', module: 11, front: 'Minimizing selection bias at follow-up', back: 'Maximize the response rate and minimize loss to follow-up.' },
    { id: 'mf-11-106', module: 11, front: 'Minimizing selection bias in trials', back: 'Allocation concealment keeps enrolment unbiased.' },
    { id: 'mf-11-027', module: 11, front: 'Minimizing information bias — tools', back: 'Validated questionnaires and calibrated instruments, with standardized data-collection procedures.' },
    { id: 'mf-11-107', module: 11, front: 'Minimizing information bias — people and design', back: 'Trained interviewers, plus objective measures and blinding where possible.' },
    { id: 'mf-11-028', module: 11, front: 'Interviewer bias — remedies', back: 'Train interviewers · use structured, standardized questionnaires · blind the interviewer to case/control (or arm) status · record and audit interviews.' },
    { id: 'mf-11-029', module: 11, front: 'Blinding participants vs blinding assessors', back: 'Blinding PARTICIPANTS prevents performance and reporting bias (placebo effects, changed behaviour); blinding OUTCOME ASSESSORS prevents detection/ascertainment bias.' },
    { id: 'mf-11-030', module: 11, front: 'Bias — direction of action', back: 'Toward the null (underestimate) OR away from it (overestimate) — and it can even reverse an association. Only NON-differential misclassification reliably points toward the null.' },
    { id: 'mf-11-031', module: 11, front: 'Residual confounding', back: 'Confounding that REMAINS after adjustment — due to imprecise confounder measurement, broad categories, or confounders never measured at all.' },
    { id: 'mf-11-032', module: 11, front: 'Confounding by indication', back: 'In observational treatment studies, the very REASON the drug was prescribed (illness severity) is associated with the outcome — making the drug look better or worse than it is.' },
    { id: 'mf-11-033', module: 11, front: 'Bias vs chance (random error)', back: 'Bias is SYSTEMATIC — it pushes results the same way repeatedly and is not diluted by bigger samples · chance is random, unpredictable and averages out as n increases.' },
    { id: 'mf-11-034', module: 11, front: 'Repairing bias after data collection', back: 'IMPOSSIBLE — once bias is built into the data, no statistical technique removes it reliably; bias must be PREVENTED at the design and data-collection stages.' },
    { id: 'mf-11-035', module: 11, front: 'Signature of systematic error', back: 'It operates CONSISTENTLY in one direction — repeating the flawed study reproduces the same wrong answer, unlike random error which scatters.' },
    { id: 'mf-11-036', module: 11, front: 'Recall bias vs interviewer bias', back: 'Recall bias lives in the RESPONDENT\u2019S memory (cases remember exposure differently) · interviewer bias lives in the INTERVIEWER\u2019S conduct (differential probing/recording).' },
    { id: 'mf-11-037', module: 11, front: 'Volunteer bias vs non-response bias', back: 'Volunteer bias = those who CONSENT/step forward differ from those who do not · non-response bias = those who REFUSE/are unavailable after selection differ from responders.' },
    { id: 'mf-11-038', module: 11, front: 'Misclassification and test accuracy', back: 'Imperfect SENSITIVITY creates false negatives and imperfect SPECIFICITY false positives — the worse the test, the greater the misclassification of exposure or outcome.' },
    { id: 'mf-11-039', module: 11, front: 'Unblinded outcome assessment in trials', back: 'When assessors know the arm, they may search harder for outcomes in one group (detection/ascertainment bias) — the reason blinded endpoint adjudication is recommended.' },
    { id: 'mf-11-040', module: 11, front: 'Differential misclassification — concrete example', back: 'Cases (who know their disease) report past exposure more completely than controls — the classification error DIFFERS between groups and can bias the OR in ANY direction.' },
    { id: 'mf-11-041', module: 11, front: 'Control selection bias', back: 'Choosing INAPPROPRIATE controls (not from the same source population as cases) makes the comparison group\u2019s exposure prevalence unrepresentative — a selection bias.' },
    { id: 'mf-11-042', module: 11, front: 'Selective outcome reporting', back: 'Only some pre-specified outcomes (the flattering ones) are reported — a reporting/information bias prevented by prospective registration and published protocols.' },
    { id: 'mf-11-043', module: 11, front: 'Synonyms: observation, ascertainment, detection', back: 'These labels all denote the same family of INFORMATION biases — errors in OBSERVING/assessing the outcome, prevented by blinding and standardized measurement.' },
    { id: 'mf-11-044', module: 11, front: 'Typical direction of recall bias', back: 'CASES tend to over-recall (or rationalize) past exposure more than controls — inflating the exposure odds among cases and exaggerating the association.' },
    { id: 'mf-11-045', module: 11, front: 'Berkson\u2019s bias — remedy', back: 'Use POPULATION-BASED cases and controls rather than sampling only hospitalized patients.' },
    { id: 'mf-11-046', module: 11, front: 'Healthy worker effect — remedy', back: 'Compare workers with an INTERNAL comparison group (e.g. less-exposed workers in the same plant) or with a similar working population, not with the general population.' },
    { id: 'mf-11-047', module: 11, front: 'Allocation concealment — prevention of selection bias', back: 'If the upcoming assignment is unpredictable, enrollers cannot tactically steer favourable patients into a preferred arm — the sequence stays hidden until assignment.' },
    { id: 'mf-11-048', module: 11, front: 'Bias — its effect on an association', back: 'It can create a SPURIOUS association, exaggerate a true one, or MASK a real one — bias always threatens the validity of the measured estimate.' },
    { id: 'mf-11-049', module: 11, front: 'Where each bias class arises', back: 'Selection bias arises at RECRUITMENT and RETENTION (who enters, who stays).\nInformation bias arises at MEASUREMENT (how exposure and outcome are recorded).' },
    { id: 'mf-11-050', module: 11, front: 'Reducing non-response', back: 'Multiple contact attempts and reminders · tracing strategies · convenient timing/venue · small incentives · keeping the questionnaire short — raising the response rate limits non-response bias.' },

  ],

  12: [
    // ---- Module 12: Sample size, power and errors ----
    { id: 'mf-12-001', module: 12, front: 'Purpose of calculating sample size', back: 'To have enough participants for adequate PRECISION and POWER to answer the question — without wasting resources (too many) or risking a false-negative result (too few).' },
    { id: 'mf-12-002', module: 12, front: 'Inputs for estimating a PROPORTION', back: 'Desired confidence level (Z) · expected prevalence/proportion (p) · absolute precision (L). Population VARIANCE is not needed for a proportion.' },
    { id: 'mf-12-003', module: 12, front: 'Z value at 95% confidence', back: '$Z = 1.96$ (≈ 2) — hence the familiar constant 4 ($Z^2$) in the simplified sample-size formulae.' },
    { id: 'mf-12-004', module: 12, front: 'Z value at 90% confidence', back: '$Z = 1.645$. Higher confidence demands a LARGER sample size.' },
    { id: 'mf-12-101', module: 12, front: 'Z value at 99% confidence', back: '$Z = 2.58$. Higher confidence demands a LARGER sample size.' },
    { id: 'mf-12-005', module: 12, front: 'Absolute precision', back: 'The margin of error tolerated on either side of the estimate, in the SAME units — e.g. \u201cprevalence estimated within ±5 percentage points\u201d.' },
    { id: 'mf-12-006', module: 12, front: 'Relative precision', back: 'Precision expressed as a PERCENTAGE of the expected value — e.g. 20% relative precision on $p = 6.5\\%$ means $d = 20\\% \\times 6.5 = 1.3\\%$.' },
    { id: 'mf-12-007', module: 12, front: 'Worked example — proportion (absolute precision)', back: '$p = 10\\%$, absolute precision 5%, $Z = 1.96$:\n$n = \\dfrac{1.96^2 \\times 10 \\times 90}{5^2} \\approx 138$.' },
    { id: 'mf-12-008', module: 12, front: 'Worked example — relative precision', back: '$p = 6.5\\%$, 20% RELATIVE precision, 95% confidence:\n$d = 1.3$ · $n = \\dfrac{1.96^2 \\times 6.5 \\times 93.5}{1.3^2} \\approx 1381$.' },
    { id: 'mf-12-009', module: 12, front: 'Worked example — estimating a MEAN', back: '$SD = 200$ ng/mL, precision $= 50$, $Z = 1.96$:\n$n = \\dfrac{1.96^2 \\times 200^2}{50^2} \\approx 62$ (rounding $Z$ to 2 gives 64). Rounding UP, report the larger value.' },
    { id: 'mf-12-010', module: 12, front: 'Worked example — mean with Z ≈ 2', back: '$SD = 2.5$ g/dL, precision $= 0.5$:\n$n = \\dfrac{2^2 \\times 2.5^2}{0.5^2} = 100$ participants.' },
    { id: 'mf-12-011', module: 12, front: 'Effect of narrowing precision on sample size', back: 'A SMALLER absolute precision (narrower margin) requires a LARGER sample — n varies inversely with the SQUARE of the precision.' },
    { id: 'mf-12-012', module: 12, front: 'Assumption of p = 0.5 when prevalence is unknown — rationale', back: '$p(1 - p)$ is MAXIMUM at $p = 0.5$ (0.25), so it yields the largest (safest) required sample size — the standard conservative assumption.' },
    { id: 'mf-12-013', module: 12, front: 'Design effect — definition', back: 'The RELATIVE change in variance caused by sampling in CLUSTERS instead of individuals — an inflation factor $> 1$.' },
    { id: 'mf-12-014', module: 12, front: 'Design effect — formula', back: '$DEFF = 1 + (m - 1)\\rho$, where $m$ = average cluster size and $\\rho$ = intracluster correlation. Sample size is multiplied by $DEFF$.' },
    { id: 'mf-12-015', module: 12, front: 'Design effect — when it must be planned', back: 'AT THE DESIGN STAGE — you cannot wait until after study completion; the EXACT value can only be computed after the data are in, but the sample size must be inflated in advance.' },
    { id: 'mf-12-016', module: 12, front: 'Sampling designs needing a design effect', back: 'CLUSTER (and multistage) sampling — e.g. immunization coverage surveys. Simple and stratified random sampling do not need it.' },
    { id: 'mf-12-017', module: 12, front: 'Finite population correction (FPC)', back: 'Reduces the required n when the sample is a LARGE fraction of a small population — the usual formulae assume a very large (effectively infinite) population.' },
    { id: 'mf-12-018', module: 12, front: 'FPC — formula', back: '$n_{adjusted} = \\dfrac{n}{1 + n/N}$, where $N$ = population size. E.g. base $n = 100$ in a population of 1000 → $\\dfrac{100}{1.1} \\approx 91$.' },
    { id: 'mf-12-019', module: 12, front: 'Adjustments NOT needed to sample size', back: 'No adjustment is made merely because the study is HOSPITAL-BASED. Adjustments ARE made for non-response, finite population size and cluster design.' },
    { id: 'mf-12-020', module: 12, front: 'Sample-size step — variable, precision and confidence', back: 'Identify the major study variable · decide desired precision · fix the confidence level (α).' },
    { id: 'mf-12-102', module: 12, front: 'Sample-size step — expected values', back: 'Obtain expected values (p, σ, effect size) from literature, pilot data or assumptions. NOT a step: adjusting for selection bias.' },
    { id: 'mf-12-103', module: 12, front: 'Sample-size step — final adjustments', back: 'Adjust the base n for design effect, finite population size and expected non-response.' },
    { id: 'mf-12-021', module: 12, front: 'Essential statistical inputs — the odd one out', back: 'Desired precision · anticipated proportion of the factor · sampling method are essential. The ALLOCATED BUDGET is not a statistical input.' },
    { id: 'mf-12-022', module: 12, front: 'Sample size inputs for an ANALYTICAL study (simple random sampling)', back: 'Desired α · desired β (power) · expected effect size from previous studies. The design effect is NOT needed — clusters are not used.' },
    { id: 'mf-12-023', module: 12, front: 'Sample size inputs for a cohort study', back: 'Proportion of outcome in the EXPOSED group ($p_1$) · proportion in the NON-EXPOSED group ($p_0$) · desired $\\alpha$ and $\\beta$. \u201cDesired precision of the outcome\u201d is a cross-sectional concept.' },
    { id: 'mf-12-024', module: 12, front: 'Effect size vs required sample size', back: 'INVERSE relationship — the LARGER the expected effect, the SMALLER the sample needed to detect it (small effects are the hardest to detect).' },
    { id: 'mf-12-025', module: 12, front: 'Cross-sectional study — sample size must account for', back: 'Expected proportion of the characteristic · design effect (if cluster sampling) · population size (finite population correction) — all of the above.' },
    { id: 'mf-12-026', module: 12, front: 'Accuracy vs precision', back: 'ACCURACY = how close an estimate is to the TRUE population value · PRECISION = repeatability/closeness of repeated estimates to each other. A precise estimate can still be inaccurate.' },
    { id: 'mf-12-027', module: 12, front: 'Standard error', back: 'The STANDARD DEVIATION of the sampling distribution of a statistic — NOT a systematic error. It quantifies how much a sample estimate would vary across samples.' },
    { id: 'mf-12-028', module: 12, front: 'Standard error of the mean — formula', back: '$SE = \\dfrac{SD}{\\sqrt{n}}$ — decreases as sample size grows, in proportion to the square root of n.' },
    { id: 'mf-12-029', module: 12, front: 'Sample size and sampling error', back: 'The LARGER the sample, the SMALLER the sampling error — the fundamental reason bigger studies give more precise estimates.' },
    { id: 'mf-12-030', module: 12, front: 'Null and alternative hypotheses', back: 'H₀ = no association/difference (what the test tries to reject) · H₁ = the association/difference of interest. Errors are defined relative to H₀.' },
    { id: 'mf-12-031', module: 12, front: 'p-value', back: 'The probability of obtaining data as extreme as (or more extreme than) observed IF the null hypothesis were true. $p < 0.05$ is the conventional threshold for significance.' },
    { id: 'mf-12-032', module: 12, front: '95% confidence interval — meaning', back: 'If the study were repeated many times, 95% of such intervals would contain the TRUE population value. An interval excluding the null value signals significance at 5%.' },
    { id: 'mf-12-033', module: 12, front: 'Sample size and CI width', back: 'LARGER samples yield NARROWER confidence intervals — greater precision around the estimate.' },
    { id: 'mf-12-034', module: 12, front: 'Sample size — not dependent on', back: 'Blinding of participants and the allocated budget. It DOES depend on the type of estimate, desired precision and study design.' },
    { id: 'mf-12-035', module: 12, front: 'Type of outcome measure → formula choice', back: 'Estimating a PROPORTION needs p (no variance) · estimating a MEAN needs the population SD ($\\sigma$) · comparing groups needs effect size plus $\\alpha$ and $\\beta$.' },
    { id: 'mf-12-036', module: 12, front: 'Sources of the population variance ($\\sigma^2$)', back: 'A PILOT study · reports of PREVIOUS studies · reasonable literature-based assumptions — variance must be estimated because it is generally unknown.' },
    { id: 'mf-12-037', module: 12, front: 'Assumptions behind standard sample-size formulae', back: 'Probability (random) sampling · population large enough to ignore finite correction · the estimate behaves normally. \u201cSampling WITH replacement\u201d is NOT an assumption.' },
    { id: 'mf-12-038', module: 12, front: 'Determinant of power — $\\alpha$ level', back: 'A stricter α (smaller Type I error) REDUCES power for a fixed sample size.' },
    { id: 'mf-12-104', module: 12, front: 'Determinant of power — sample size', back: 'A LARGER sample size increases statistical power.' },
    { id: 'mf-12-105', module: 12, front: 'Determinant of power — true effect size', back: 'A LARGER true effect is easier to detect, increasing power.' },
    { id: 'mf-12-106', module: 12, front: 'Determinant of power — variability', back: 'Greater variability (σ) REDUCES power.' },
    { id: 'mf-12-039', module: 12, front: 'The α–β trade-off', back: 'Making $\\alpha$ stricter (e.g. 5% → 1%) raises $\\beta$ (lowers power) UNLESS the sample size is increased — you cannot tighten one error rate for free.' },
    { id: 'mf-12-040', module: 12, front: '$\\beta$ error in comparative studies', back: '$\\beta$ (Type II error) must be SPECIFIED when planning comparative/analytical studies — it sets the power. Precision (not $\\beta$) drives purely descriptive studies.' },
    { id: 'mf-12-041', module: 12, front: 'Estimation vs comparison studies', back: 'Estimation (cross-sectional/descriptive): sample size driven by PRECISION and confidence level.\nComparison (analytical): sample size driven by $\\alpha$, $\\beta$/POWER and effect size.' },
    { id: 'mf-12-042', module: 12, front: 'Sampling error', back: 'The error from observing a SAMPLE instead of the whole population — random in nature and reduced by increasing the sample size.' },
    { id: 'mf-12-043', module: 12, front: 'Non-sampling error', back: 'Errors from measurement, non-response, data entry and processing — NOT fixed by a larger sample; reduced by better design, training and quality control.' },
    { id: 'mf-12-044', module: 12, front: 'Design effect — worked example', back: 'Base sample 210 individuals, $DEFF = 1.5$ → recruit $210 \\times 1.5 = 315$ individuals to achieve the same effective precision.' },
    { id: 'mf-12-045', module: 12, front: 'Non-response — worked adjustment', back: 'Required $n = 400$, expected non-response 20% → recruit $\\dfrac{400}{0.8} = 500$ participants.' },
    { id: 'mf-12-046', module: 12, front: 'Sample size for comparing two proportions', back: 'Requires the expected outcome proportions in BOTH groups ($p_1$ and $p_2$), plus $\\alpha$ and $\\beta$/power — the minimum difference ($p_1 - p_2$) drives the calculation.' },
    { id: 'mf-12-047', module: 12, front: 'Relative precision — worked conversion', back: 'Expected anaemia prevalence 28%, relative precision 10% → absolute precision $d = 10\\% \\times 28 = 2.8$ percentage points.' },
    { id: 'mf-12-048', module: 12, front: 'Worked example — anaemia prevalence', back: '$p = 28\\%$, $d = 2.8$, $Z \\approx 2$:\n$n = \\dfrac{2^2 \\times 28 \\times 72}{2.8^2} \\approx 1029$ participants.' },
    { id: 'mf-12-049', module: 12, front: 'Power ↔ β mapping', back: '$\\text{Power} = 1 - \\beta$. Power 80% ↔ $\\beta = 0.20$ · power 90% ↔ $\\beta = 0.10$. The recommended MINIMUM power for analytical studies is 80%.' },
    { id: 'mf-12-050', module: 12, front: 'Confounders in the sample-size formula', back: 'Not built in — the standard formula captures only the CRUDE association. Confounders are handled by the +10% per additional variable inflation rule, not by the base formula.' }
  ]
};